function practice(id,name,cost,group,summary,gains,losses,relation,observation){return {id,name,cost,group,types:['crop','agro'],summary,gains,losses,relation,observation};}
export const PRACTICES=[
 practice('notill','Plantio direto',3,'soil','Semear com mínimo revolvimento do solo.', ['Menor perturbação da estrutura e dos organismos do solo.','Com cobertura e rotação, o sistema amplia a proteção e a estabilidade da produção.'],['Sem cobertura e diversificação, o benefício é limitado.','A implantação exige planejamento e equipamento adequado.'],'O sistema de plantio direto combina mínimo revolvimento, cobertura permanente e rotação; não é apenas deixar de arar.','A semeadura passa a ocorrer sem revolvimento amplo. No jogo, o benefício completo aparece quando cobertura e rotação também estão presentes.'),
 practice('crop_rotation','Rotação de culturas',3,'soil','Alternar espécies comerciais ao longo dos ciclos.', ['Raízes e resíduos diferentes diversificam os recursos do solo.','A alternância reduz a continuidade de hospedeiros para parte das pragas.'],['A produção de abóbora cede parte do espaço e do tempo a outros cultivos.','O planejamento e a comercialização ficam mais diversos.'],'Diversificar hospedeiros e resíduos muda as relações com herbívoros, decompositores e microrganismos.','O setor mantém a produção agrícola, agora com alternância de espécies. A produção é diversificada e a pressão de herbívoros diminui parcialmente.'),
 practice('compost','Composto orgânico',3,'soil','Incorporar ao manejo resíduos previamente compostados.', ['A matéria orgânica alimenta a atividade dos decompositores.','A melhoria do solo é gradual e pode sustentar as colheitas futuras.'],['Coleta, compostagem e transporte exigem tempo e trabalho.','A liberação de nutrientes é gradual; não resolve toda limitação imediatamente.'],'Decompositores e microrganismos transformam matéria orgânica e participam da ciclagem de nutrientes.','O composto passa a contribuir para a recuperação do solo a cada ciclo. A liberação de nutrientes é mais gradual que a resposta à adubação mineral.'),
 practice('fertilizer','Adubação mineral',2,'soil','Disponibilizar nutrientes para a cultura neste período.', ['A disponibilidade imediata de nutrientes favorece a produção.','Pode responder a uma limitação nutricional durante a safra.'],['Há gasto com insumos e o efeito precisa ser renovado.','Parte dos nutrientes pode alcançar a água, sobretudo com solo exposto e chuva intensa.'],'A absorção pelas raízes compete com perdas por transporte de água; fornecer nutrientes não recompõe, sozinho, a estrutura do solo.','A resposta produtiva dura dois ciclos. No modelo, solo coberto reduz parte das perdas de nutrientes para a água; a adubação não recupera sozinha a estrutura do solo.'),
 practice('bio_growth','Bioinsumo para crescimento',3,'life','Usar microrganismos promotores do crescimento vegetal.', ['A associação com microrganismos pode melhorar o aproveitamento de nutrientes.','A produção recebe um benefício condicionado ao ambiente do solo.'],['O resultado depende do agente, da cultura e das condições locais.','Neste cenário, o efeito é menor com solo degradado ou sob pressão do inseticida de amplo espectro.'],'Interações entre plantas e microrganismos podem favorecer a nutrição; bioinsumos para crescimento não têm a mesma função de um bioinseticida.','O bioinsumo atua por três ciclos no jogo. Sua contribuição é menor em solo degradado ou quando há efeito do inseticida de amplo espectro. Essa interação é uma hipótese didática, não uma regra para todos os produtos.'),
 practice('microbial','Bioinseticida microbiano',3,'life','Aplicar um agente biológico contra o inseto herbívoro.', ['Reduz parte das perdas por herbivoria durante seu período de ação.','O agente seletivo representado no jogo preserva mais os polinizadores e predadores.'],['A resposta é parcial e depende do organismo-alvo e das condições ambientais.','A compatibilidade com outros produtos precisa ser considerada; não elimina toda a herbivoria.'],'O controle usa a interação entre microrganismo e hospedeiro, distinta da predação por insetos ou aves.','O agente seletivo simulado reduz a herbivoria por dois ciclos. O inseticida de amplo espectro compromete parte de sua ação neste cenário; outros agentes e produtos podem apresentar respostas diferentes.'),
 practice('mip','Manejo integrado de pragas',3,'life','Monitorar a pressão e intervir de forma seletiva.', ['A decisão de controle considera a pressão de herbivoria e os inimigos naturais.','Evita uma intervenção uniforme quando a pressão é pequena.'],['Exige observação frequente e conhecimento sobre os organismos.','Parte da herbivoria continua ocorrendo; o objetivo não é eliminar todos os insetos.'],'Monitoramento liga herbivoria, predação e tomada de decisão; o controle seletivo entra quando a pressão simulada é maior.','O monitoramento fica ativo. Na fase de herbivoria, o modelo aciona uma resposta seletiva somente quando a perda potencial supera o limiar didático. Não é um limiar de campo.'),
 practice('drip','Irrigação por gotejamento',4,'soil','Fornecer água localizada na zona das raízes.', ['Reduz parte da perda produtiva durante a seca.','A distribuição localizada permite direcionar a água à cultura.'],['Instalação e manutenção consomem recursos.','A retirada de água reduz a disponibilidade compartilhada; muitos setores irrigados podem competir entre si.'],'Plantas e usos humanos compartilham a água disponível; maior estabilidade de um setor pode pressionar o recurso comum.','O sistema ajuda o cultivo na seca, mas passa a retirar água do recurso compartilhado. Quanto mais áreas irrigadas, menor a disponibilidade; com água escassa, o benefício diminui.')
];
export const fullSPD=t=>Boolean(t.cover&&t.noTill&&t.cropRotation);
export const groupFor=a=>a.group||({cover:'soil',biocontrol:'life',spray:'life'}[a.id])||'use';
export const extraTileDefaults={noTill:false,cropRotation:false,compost:false,bioGrowth:0,microbial:0,mip:false,fertilizer:0,irrigation:false};
